"use strict";function loadDetailMyOT(n){$.ajax({url:_global.root+"overtime/MyOvertimeData",type:"POST",dataType:"html",data:{year:$("#Year").val()},beforeSend:function(){n||$("#myOT .loading-process").fadeIn(300)},success:function(n){$("#dataMyOT tbody").html(n)},error:function(){notifyError(_messages.errorTryAgain)},complete:function(){n||$("#myOT .loading-process").fadeOut(300)}})}function initButtonForMyOT(){$("#myOT #btn-submit").click(function(){loadDetailMyOT(!1)})}function initTooltip(){var n=$("#memberOT .contextmenu");n.mouseover(function(){$(this).find(".drop-menu").show()});n.mouseout(function(){$(this).find(".drop-menu").hide()})}function loadMemberOTDetail(){$("#memberOT .loading-process").fadeIn(300);$.post(_global.root+"Overtime/MemberOvertimeData",$("#memberOT #form").serialize(),function(n){$("#dataMemberOT tbody").html(n);initTooltip();initDeleteForMemberOT();$("#memberOT .loading-process").fadeOut(300)})}function rejectRequest(n){confirm("<p>Are you sure you want to reject this request?<\/p>",function(){$("#memberOT .loading-process").fadeIn(200);$.post(_global.root+"Overtime/RejectRequest",{id:n},function(n){n.IsSuccessful?loadMemberOTDetail():($("#memberOT .loading-process").fadeOut(500),notifyError(n.Message))})})}function disapproveRequest(n){confirm("<p>Are you sure you want to disapprove this request?<\/p>",function(){$("#memberOT .loading-process").fadeIn(200);$.post(_global.root+"Overtime/DisapproveRequest",{id:n},function(n){n.IsSuccessful?loadMemberOTDetail():($("#memberOT .loading-process").fadeOut(500),notifyError(n.Message))})})}function approveRequest(n,t){confirm("<p>Are you sure you want to approve this request?<\/p>",function(){$("#memberOT .loading-process").fadeIn(200);$.post(_global.root+"Overtime/ApproveRequest",{id:n,createdBy:t},function(n){n.IsSuccessful?loadMemberOTDetail():($("#memberOT .loading-process").fadeOut(500),notifyError(n.Message))})})}function resetRequest(n){confirm("<p>Are you sure you want to reset this request?<\/p>",function(){$("#memberOT .loading-process").fadeIn(200);$.post(_global.root+"Overtime/ResetRequest",{id:n},function(n){n.IsSuccessful?loadMemberOTDetail():($("#memberOT .loading-process").fadeOut(500),notifyError(n.Message))})})}function processRequest(n,t){var i=t.$trigger.attr("requestId"),r=t.$trigger.attr("createdBy");switch(n){case"approve":approveRequest(i,r);break;case"disapprove":disapproveRequest(i);break;case"reject":rejectRequest(i);break;case"reset":resetRequest(i)}}function bindPendingMenu(){if(IsManager)$.contextMenu({selector:"#memberOT .Pending",trigger:"left",callback:function(n,t){processRequest(n,t)},items:{approve:{name:"Approve",icon:"approve"},reject:{name:"Reject",icon:"reject"}}})}function bindApproveMenu(){if(IsManager)$.contextMenu({selector:"#memberOT .Approve",trigger:"left",callback:function(n,t){processRequest(n,t)},items:{disapprove:{name:"Disapprove",icon:"reject"}}})}function bindRejectMenu(){if(IsManager)$.contextMenu({selector:"#memberOT .Reject",trigger:"left",callback:function(n,t){processRequest(n,t)},items:{reset:{name:"Reset",icon:"refresh"}}})}function initButtonForMemberOT(){$("#memberOT #btn-submit").click(function(){validateFromDateAndToDate()&&loadMemberOTDetail()})}function initDeleteForMemberOT(){$(".delete-overtime").on("click",function(){var n=$(this).attr("requestId");confirm("<p>Are you sure you want to delete this request?<\/p>",function(){$.ajax({url:_global.root+"Overtime/Delete",method:"POST",data:{id:n},success:function(n){n.IsSuccessful?loadMemberOTDetail():notifyError(n.Message)},error:function(n,t,i){notifyError(t+": "+i)}})})})}function loadOTRequestDetail(){$("#OTRequest .loading-process").fadeIn(300);$.post(_global.root+"overtime/OvertimeRequestDetail",$("#OTRequest #form").serialize(),function(n){$("#dataOTRequest tbody").html(n);floatThead("table#data");$("#OTRequest .loading-process").fadeOut(300)})}function initButtonForOTRequest(){$("#OTRequest #btn-submit").click(function(){$("#OTRequest #form #OvertimeId").val(null);loadOTRequestDetail()})}function setDateTimeRangeForOTRequest(n){var i=new Date($("#FromDateOT").val()),r=new Date($("#ToDateOT").val()),t=$("#DateTime-Now").val();i=$.format.date(i,"dd MMM, yyyy");r=$.format.date(r,"dd MMM, yyyy");switch(parseInt(n)){case 1:r=i=Date.parse(t).toString("dd MMM, yyyy");break;case 2:r=i=Date.parse(t).add(-1).days().toString("dd MMM, yyyy");break;case 3:i=Date.parse(t).moveToDayOfWeek(0,-1).toString("dd MMM, yyyy");r=Date.parse(t).toString("dd MMM, yyyy");break;case 4:i=Date.parse(t).moveToDayOfWeek(0,-1).add(-7).days().toString("dd MMM, yyyy");r=Date.parse(t).moveToDayOfWeek(0,-1).add(-1).days().toString("dd MMM, yyyy");break;case 5:i=Date.parse(t).moveToFirstDayOfMonth().toString("dd MMM, yyyy");r=Date.parse(t).toString("dd MMM, yyyy");break;case 6:i=Date.parse(t).add(-1).months().moveToFirstDayOfMonth().toString("dd MMM, yyyy");r=Date.parse(t).add(-1).months().moveToLastDayOfMonth().toString("dd MMM, yyyy");break;case 7:i=Date.parse(t).add(-1).months().moveToFirstDayOfMonth().toString("dd MMM, yyyy");r=Date.parse(t).toString("dd MMM, yyyy")}$("#FromDateOT").val(i);$("#ToDateOT").val(r)}function initFormOTRequest(){initDatePicker("#OTRequest .datepicker");initButtonForOTRequest();initAutocomplete("#OTRequest #CreatedName","#OTRequest #CreatedBy",!1);initAutocomplete("#OTRequest #Employee","#OTRequest #EmployeeId",!1);$("#OTRequest #Date").on("change",function(){setDateTimeRangeForOTRequest($(this).val())});loadOTRequestDetail()}function loadOTRequest(n,t,i,r,u,f){$.ajax({url:_global.root+"overtime/overtimerequest",type:"GET",data:{CreatedBy:t,FromDateOT:i,ToDateOT:r,Status:u,OvertimeId:f},dataType:"html","async":!1,beforeSend:function(){n||$("#OTRequest .loading-process").fadeIn(300)},success:function(n){$("#OTRequest").html(n);$("select").material_select();initFormOTRequest()},error:function(){notifyError(_messages.errorTryAgain)},complete:function(){n||$("#OTRequest .loading-process").fadeOut(300)}})}function initFormMemberOT(){initDatePicker("#memberOT .datepicker");initButtonForMemberOT();initAutocomplete("#memberOT #CreatedName","#memberOT #CreatedBy",!1);$("#memberOT #Date").on("change",function(){setDateTimeRange($(this).val())});loadMemberOTDetail();bindPendingMenu();bindApproveMenu();bindRejectMenu()}function loadMemberOvertime(n){$.ajax({url:_global.root+"overtime/memberovertime",type:"GET",dataType:"html","async":!1,beforeSend:function(){n||$("#memberOT .loading-process").fadeIn(300)},success:function(n){$("#memberOT").append(n);initFormMemberOT()},error:function(){notifyError(_messages.errorTryAgain)},complete:function(){n||$("#memberOT .loading-process").fadeOut(300)}})}function loadMyOvertime(){$.ajax({url:_global.root+"overtime/myovertime",type:"GET",dataType:"html","async":!1,beforeSend:function(){$("#myOT .loading-process").fadeIn(300)},success:function(n){$("#myOT").append(n);initButtonForMyOT();loadDetailMyOT(!0)},error:function(){notifyError(_messages.errorTryAgain)},complete:function(){$("#myOT .loading-process").fadeOut(300)}})}function loadDetailTotalMembers(n,t,i,r){let u=$("#memberOT #FromDate").val(),f=$("#memberOT #ToDate").val();loadOTRequest(n,t,u,f,i,r);$("ul.tabs").tabs("select_tab","OTRequest")}$(document).ready(function(){loadMyOvertime(!0);(_global.roles!==""||_global.teamId==="13")&&loadMemberOvertime(!0);loadOTRequest(!0);$("select").material_select()});